package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string
	ErDept  string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevDept string = "   "
var WsRegHours decimal.Decimal = decimal.Zero
var WsOtHours decimal.Decimal = decimal.Zero
var WsGross decimal.Decimal = decimal.Zero
var WsDeptTotal decimal.Decimal = decimal.Zero
var WsDeptCount int64 = 0
var WsGrandTotal decimal.Decimal = decimal.Zero
var WsGrandCount int64 = 0
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var curRec EmpRec
var inputLines []string
var inputIdx int
var inputOpen bool

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func parseDigits(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64
	for _, c := range s {
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		}
	}
	return v
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func storeDec(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := v.Truncate(scale)
	if intDigits < 0 {
		return t
	}
	modExp := int64(intDigits) + int64(scale)
	mod := decimal.NewFromInt(1).Shift(int32(modExp))
	sign := t.Sign()
	a := t.Abs()
	m := a.Mod(mod)
	if sign < 0 {
		m = m.Neg()
	}
	// ensure scale
	m = m.Truncate(scale)
	return m
}

func storeInt(v int64, digits int) int64 {
	if digits <= 0 {
		return v
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// COBOL unsigned: keep low-order digits; handle negative by sign-preserving mod
	if v >= 0 {
		return v % mod
	}
	av := -v
	r := av % mod
	return -r
}

func formatEdited(v decimal.Decimal, pattern string) string {
	dot := strings.Index(pattern, ".")
	var intPat, fracPat string
	if dot >= 0 {
		intPat = pattern[:dot]
		fracPat = pattern[dot+1:]
	} else {
		intPat = pattern
		fracPat = ""
	}
	// count integer digit placeholders
	intPlace := []byte{}
	for i := 0; i < len(intPat); i++ {
		c := intPat[i]
		if c == 'Z' || c == '9' {
			intPlace = append(intPlace, c)
		}
	}
	nInt := len(intPlace)
	// count frac digit placeholders
	fracCount := 0
	for i := 0; i < len(fracPat); i++ {
		c := fracPat[i]
		if c == 'Z' || c == '9' {
			fracCount++
		}
	}
	scale := int32(fracCount)
	// MOVE truncates toward zero (values here are exact)
	t := v.Truncate(scale)
	neg := t.Sign() < 0
	a := t.Abs()
	// integer part string
	intPart := a.Truncate(0)
	intStr := intPart.String()
	// String may contain decimal point? Truncate(0) should be integer
	if idx := strings.Index(intStr, "."); idx >= 0 {
		intStr = intStr[:idx]
	}
	// strip sign if any
	intStr = strings.TrimPrefix(intStr, "-")
	intStr = strings.TrimPrefix(intStr, "+")
	// keep low-order digits
	if len(intStr) > nInt {
		intStr = intStr[len(intStr)-nInt:]
	}
	// pad with leading zeros to nInt
	if len(intStr) < nInt {
		intStr = strings.Repeat("0", nInt-len(intStr)) + intStr
	}
	// fractional digits
	fracStr := ""
	if fracCount > 0 {
		fracPart := a.Sub(intPart).Abs()
		// multiply to get digits
		mult := decimal.NewFromInt(1).Shift(scale)
		fdig := fracPart.Mul(mult).Truncate(0)
		s := fdig.String()
		if idx := strings.Index(s, "."); idx >= 0 {
			s = s[:idx]
		}
		s = strings.TrimPrefix(s, "-")
		if len(s) > fracCount {
			s = s[len(s)-fracCount:]
		}
		if len(s) < fracCount {
			s = strings.Repeat("0", fracCount-len(s)) + s
		}
		fracStr = s
	}
	// suppression
	supp := make([]bool, nInt)
	suppressing := true
	for k := 0; k < nInt; k++ {
		ph := intPlace[k]
		dg := intStr[k]
		if !suppressing {
			supp[k] = false
		} else {
			if ph == '9' {
				supp[k] = false
				suppressing = false
			} else { // Z
				if dg != '0' {
					supp[k] = false
					suppressing = false
				} else {
					supp[k] = true
				}
			}
		}
	}
	// build output
	var out []byte
	intIdx := 0
	fracIdx := 0
	// need helper to know if any non-suppressed to left of position
	// precompute prefixNonSupp count
	for i := 0; i < len(pattern); i++ {
		c := pattern[i]
		switch c {
		case 'Z', '9':
			// determine if this is int or frac part by position relative to dot
			isInt := dot < 0 || i < dot
			if isInt {
				if supp[intIdx] {
					out = append(out, ' ')
				} else {
					out = append(out, intStr[intIdx])
				}
				intIdx++
			} else {
				out = append(out, fracStr[fracIdx])
				fracIdx++
			}
		case ',':
			// space if all int digits to left are suppressed
			leftSupp := true
			for k := 0; k < intIdx; k++ {
				// intIdx counts int placeholders consumed so far; but need mapping:
				// intIdx is number consumed. Check those.
				if !supp[k] {
					leftSupp = false
					break
				}
			}
			if leftSupp {
				out = append(out, ' ')
			} else {
				out = append(out, ',')
			}
		case '.':
			out = append(out, '.')
		default:
			out = append(out, c)
		}
	}
	_ = neg
	return string(out)
}

func formatUneditedInt(v int64, width int) string {
	neg := v < 0
	av := v
	if neg {
		av = -v
	}
	s := fmt.Sprintf("%d", av)
	if len(s) > width {
		s = s[len(s)-width:]
	}
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	// negatives in unsigned fields: ignore sign (values are non-negative here)
	return s
}

func loadInput() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		inputLines = nil
		return
	}
	// split line sequential
	raw := strings.Split(string(data), "\n")
	// if file ends with newline, last element is "" from trailing split -> drop it
	if len(raw) > 0 && raw[len(raw)-1] == "" {
		// check that data actually ended with newline
		if len(data) > 0 && data[len(data)-1] == '\n' {
			raw = raw[:len(raw)-1]
		}
	}
	inputLines = make([]string, 0, len(raw))
	for _, l := range raw {
		if strings.HasSuffix(l, "\r") {
			l = l[:len(l)-1]
		}
		inputLines = append(inputLines, l)
	}
}

func parseRecord(line string) EmpRec {
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	}
	if len(line) > 17 {
		line = line[:17]
	}
	id := line[0:5]
	dept := line[5:8]
	hStr := line[8:12]
	rStr := line[12:17]
	h := parseDigits(hStr)
	r := parseDigits(rStr)
	return EmpRec{
		ErId:    id,
		ErDept:  dept,
		ErHours: decimal.New(h, -1),
		ErRate:  decimal.New(r, -2),
	}
}

func MAINPARA() {
	inputOpen = true
	loadInput()
	inputIdx = 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	if !isFirstRecord() {
		DEPTBREAKPARA()
	}
	inputOpen = false
	GRANDPARA()
}

func READPARA() {
	if !inputOpen || inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	curRec = parseRecord(line)
}

func PROCESSPARA() {
	if isFirstRecord() {
		WsPrevDept = curRec.ErDept
		WsFirstFlag = "N"
	} else {
		if curRec.ErDept != WsPrevDept {
			DEPTBREAKPARA()
			WsPrevDept = curRec.ErDept
		}
	}
	PAYPARA()
	READPARA()
}

func PAYPARA() {
	forty := decimal.NewFromInt(40)
	if curRec.ErHours.GreaterThan(forty) {
		WsRegHours = storeDec(decimal.NewFromInt(40), 3, 1)
		WsOtHours = storeDec(curRec.ErHours.Sub(forty), 3, 1)
	} else {
		WsRegHours = storeDec(curRec.ErHours, 3, 1)
		WsOtHours = storeDec(decimal.Zero, 3, 1)
	}
	onePtFive := decimal.New(15, -1)
	expr := WsRegHours.Mul(curRec.ErRate).Add(WsOtHours.Mul(curRec.ErRate).Mul(onePtFive))
	WsGross = storeDec(expr.Round(2), 7, 2)
	WsDeptTotal = storeDec(WsDeptTotal.Add(WsGross), 9, 2)
	WsDeptCount = storeInt(WsDeptCount+1, 3)
	WsGrandTotal = storeDec(WsGrandTotal.Add(WsGross), 11, 2)
	WsGrandCount = storeInt(WsGrandCount+1, 5)
	WsHoursEd = formatEdited(curRec.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(curRec.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	fmt.Fprintf(os.Stdout, "%s %s %s %s %s\n", padRight(curRec.ErId, 5), padRight(curRec.ErDept, 3), WsHoursEd, WsRateEd, WsGrossEd)
}

func DEPTBREAKPARA() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	fmt.Fprintf(os.Stdout, "%s%s%s%s%s%s\n", "  DEPT ", padRight(WsPrevDept, 3), " EMPLOYEES: ", formatUneditedInt(WsDeptCount, 3), " TOTAL: ", WsDeptEd)
	WsDeptTotal = storeDec(decimal.Zero, 9, 2)
	WsDeptCount = storeInt(0, 3)
}

func GRANDPARA() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	fmt.Fprintf(os.Stdout, "%s%s%s%s\n", "GRAND TOTAL (", formatUneditedInt(WsGrandCount, 5), "): ", WsGrandEd)
}

func main() {
	MAINPARA()
}
